const t={ui:{fig:"Abb. 1",title:"Handytasche · Anatomie",svgLabel:"Eine isometrische Zeichnung der gefütterten Handytasche mit Klappe und drei Fächern und wie sie Schritt für Schritt genäht wird.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Zerlegen",putTogether:"Zusammensetzen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT",cutTitle:"Handytasche · Zuschnittmaße",cutAlt:"Zuschnittplan für eine gefütterte Handytasche mit Klappe: Außenstoff, Futter und Bügeleinlage je als langes Teil 57 × 19 cm und Klappenteil 31 × 13 cm, dazu zwei Quadrate 5 × 5 cm für die Schlaufen.",cutCaption:"Alle Zuschnitte mit ihren Maßen – wie in Schritt 1."},stitches:{straight:"Geradstich"},labels:{cm57:"57 cm",cm19:"19 cm",cm31:"31 cm",cm13:"13 cm",cm5:"5 cm",cm11:"11 cm",outerPrint:"außen · bedruckte Baumwolle",liningSame:"Futter · gleiche Maße",ifaceSame:"Einlage · gleiche Maße",flapPieces:"Klappenteile",ears2:"2 × Schlaufen",wrongSideUp:"außen, links oben",ironOn:"aufbügeln",outerOnly:"nur Außenteile",faceDown:"rechts unten, mittig",seam05:"Naht 0,5 cm",openOut:"aufklappen: ein T",liningSameT:"Futter: gleiches T",rightSides:"rechts auf rechts",roundObject:"runder Deckel",roundCorners:"runde Ecken",opening6:"6 cm Wendeöffnung",oppositeFlap:"gegenüber der Klappe",clipCorners:"Ecken einschneiden",turnOut:"auf rechts wenden",press:"bügeln",topstitch05:"0,5 cm absteppen",closesOpening:"schließt die Öffnung",turnOver:"Futter oben",foldHalf:"zur Hälfte falten",fromFold:"ab dem Bruch",throughBoth:"durch beide Lagen",twoLines:"zwei Nähte",openFlap:"Klappe aufklappen",seamsMiddle:"Nähte zur Mitte",accordion:"wie eine Ziehharmonika",pockets3:"3 Fächer",likeStraps:"wie die Henkel",intoLoop:"zur Schlaufe falten",makeTwo:"zwei Stück",overTop:"umschlagen",backAndFlap:"Rückseite + Klappe",earsIn:"Schlaufen oben",clipIt:"Seiten klammern",edgeStitch:"knapp an der Kante",allLayers:"durch alle Lagen",snapFlap:"Knopf: Klappenmitte",whereItLands:"wo er trifft",secondHalf:"zweite Hälfte",insidePockets:"Handy · Geld · Karten"},steps:[{title:"Die fertige Tasche",text:"Eine kleine gefütterte Tasche für Handy, Geld und Karten: drei Fächer innen, eine Klappe mit Kunststoff-Druckknopf und zwei kleine Schlaufen oben. Die Kette ist nur eine Idee – im Video gibt es keine; an die Schlaufen passt jede Kette oder jeder Riemen mit Karabinern. Tippe auf die Tasche, um sie zu zerlegen."},{title:"Zuschneiden",text:"Außen aus bedruckter Baumwolle: ein langes Teil 57 × 19 cm und ein Klappenteil 31 × 13 cm. Futter und Bügeleinlage: die gleichen zwei Maße. Zwei Quadrate 5 × 5 cm für die Schlaufen.",details:["Schneide aus bedruckter Baumwolle das lange Teil 57 × 19 cm und das Klappenteil 31 × 13 cm zu.","Das Futter genauso: 57 × 19 cm und 31 × 13 cm.","Bügeleinlage in denselben zwei Maßen – nur für die Außenteile.","Für die Schlaufen schneide zwei Quadrate 5 × 5 cm aus bedruckter Baumwolle zu.","Alle Nahtzugaben in dieser Tasche sind 0,5 cm."]},{title:"Einlage aufbügeln",text:"Bügle die Einlage auf die linke Seite der beiden Außenteile. Das Futter bekommt keine.",details:["Lege das lange Außenteil und das Klappenteil mit der linken Seite nach oben.","Lege die Einlage mit der Klebeseite nach unten Kante an Kante darauf und bügle sie auf.","Die Futterteile bekommen keine Einlage."]},{title:"Das T nähen",text:"Lege das Klappenteil rechts auf rechts quer über die Mitte des langen Teils, seine 13-cm-Kante auf die lange Kante. Nähe 0,5 cm von der Kante und klappe es auf: ein T. Aus dem Futter nähst du das gleiche T.",details:["Lege das lange Teil mit der rechten Seite nach oben.","Lege das Klappenteil mit der rechten Seite nach unten quer darauf: seine 13-cm-Kante genau mittig auf einer langen Kante, Kante an Kante.","Nähe entlang dieser Kante 0,5 cm breit und klappe das Klappenteil auf: Die beiden Teile bilden ein T.","Aus den Futterteilen nähst du genauso ein T."]},{title:"Die Klappe abrunden",text:"Lege das Futter-T rechts auf rechts auf das Außen-T. Runde die beiden Ecken am Ende der Klappe ab: Zeichne um einen beliebigen runden Gegenstand und schneide an der Linie entlang.",details:["Lege das Futter-T mit der rechten Seite nach unten auf das Außen-T, Kanten bündig, und halte es mit Stoffklammern fest.","Am Ende des Klappenteils zeichnest du an beiden Ecken um einen beliebigen runden Gegenstand – einen Glasdeckel, eine Rolle Klebeband.","Schneide an den Linien entlang: Die Klappe bekommt runde Ecken."]},{title:"Ringsum nähen",text:"Nähe ringsum 0,5 cm von der Kante und lass in der Mitte der langen Kante gegenüber der Klappe eine 6-cm-Öffnung. Schneide die Ecken ein.",details:["Beginne an einem Ende der Öffnung: Die 6 cm bleiben offen – mittig auf der langen Kante, gegenüber dem Klappenteil.","Nähe das ganze T ringsum 0,5 cm von der Kante und höre am anderen Ende der Öffnung auf.","Schneide die Nahtzugabe in den beiden inneren Ecken des T ein – knapp vor der Nahtlinie – und an den runden Ecken, damit sie flach liegen."]},{title:"Wenden",text:"Wende das T durch die Öffnung auf rechts. Drücke die Ecken aus und bügle es.",details:["Ziehe das ganze T durch die Öffnung.","Drücke die Ecken und das runde Ende der Klappe aus.","Bügle es flach, die Kanten der Öffnung nach innen eingeschlagen."]},{title:"Ringsum absteppen",text:"Steppe das ganze T ringsum 0,5 cm von der Kante ab. Dieselbe Naht schließt auch die Öffnung.",details:["Steppe 0,5 cm breit an der ganzen Kante entlang.","Halte an der Öffnung die eingeschlagenen Kanten bündig: Die Steppnaht schließt sie."]},{title:"Falten und anzeichnen",text:"Dreh das T mit dem Futter nach oben und falte das lange Teil zur Hälfte – das Klappenteil faltet sich dabei längs zur Hälfte. Zeichne Linien 11 und 22 cm vom Bruch an.",details:["Dreh das T mit dem Futter nach oben.","Falte das lange Teil zur Hälfte, Futter innen: Der Bruch läuft durch die Mitte des Klappenteils, das sich längs zur Hälfte faltet.","Miss mit dem Maßband 11 cm vom Bruch ab und von dieser Markierung noch einmal 11 cm: Linien 11 und 22 cm vom Bruch. Zieh sie mit dem Lineal quer."]},{title:"Zwei Linien nähen",text:"Nähe beide Linien durch beide Hälften. Die Hälften sind jetzt verbunden: Diese Nähte teilen die Tasche in Fächer.",details:["Nähe die erste Linie durch beide Lagen.","Nähe die zweite Linie genauso.","Zwischen Bruch und erster Naht und zwischen den beiden Nähten bilden die Hälften zwei Schlaufen."]},{title:"Wie eine Ziehharmonika falten",text:"Klappe das Klappenteil wieder flach auf. Die Nähte rutschen in die Mitte, und das lange Teil faltet sich wie eine Ziehharmonika: drei Fächer.",details:["Klappe das Klappenteil flach auf.","Streiche das lange Teil so glatt, dass seine Mitte – der Bruch – am Ende des Klappenteils liegt und beide Nähte in der Mitte.","Es faltet sich wie eine Ziehharmonika: drei Fächer hintereinander."]},{title:"Schlaufen machen",text:"Falte jedes 5 × 5 cm große Quadrat wie die Henkel der Tote Bag: zur Hälfte, die Kanten zum Bruch, noch einmal zur Hälfte. Dann zur Hälfte zu einer Schlaufe. Mach zwei.",details:["Falte das Quadrat zur Hälfte und öffne es wieder.","Schlag beide Kanten bis zu diesem Bruch ein und falte noch einmal zur Hälfte: ein schmaler Streifen, vier Lagen dick.","Falte den Streifen zur Hälfte zu einer kleinen Schlaufe. Mach zwei."]},{title:"Die Klappe umschlagen",text:"Schlag das lange Klappenteil über die Fächer um: Es führt um den Boden und an der Rückseite hoch, sein Ende ragt oben als Klappe heraus. Steck oben in jede Seite eine Schlaufe – zwischen Rückseite und Fächer.",details:["Schlag das Klappenteil über die Fächer. Sein Bruch ist der Boden der Tasche und schließt jedes Fach unten.","Der Rest ist die Rückseite; ihr Ende ragt oben heraus – das ist die Klappe.","Steck oben in jede Seite eine Schlaufe, zwischen Rückseite und Fächer, die Schlaufe nach außen.","Halte die Seiten mit Stoffklammern fest."]},{title:"Die Seiten nähen",text:"Nähe beide Seiten knapp an der Kante, durch alle Lagen und die Schlaufen.",details:["Nähe eine Seite knapp an der Kante der Falten, durch jede Lage und die Schlaufe.","Nähe die andere Seite genauso."]},{title:"Den Druckknopf setzen",text:"Setze eine Hälfte des Kunststoff-Druckknopfs mittig auf die Klappe, auf die Steppnaht. Klapp die Klappe herunter, markiere, wo er trifft, und setze dort die andere Hälfte.",details:["Setze die erste Hälfte des Knopfs mittig an das runde Ende der Klappe, auf die Steppnaht.","Klapp die Klappe über die Vorderseite und markiere, wo der Knopf trifft.","Setze dort die zweite Hälfte.","Innen: das Handy ins Fach an der Rückseite, Geld ins mittlere, Karten ins vordere."]}],legend:[{title:"Außen",text:"bedruckte Baumwolle · langes Teil 57 × 19 cm und Klappenteil 31 × 13 cm"},{title:"Einlage",text:"Bügeleinlage · die gleichen zwei Maße, nur auf den Außenteilen"},{title:"Futter",text:"rosa Baumwolle · die gleichen zwei Maße, ohne Einlage"},{title:"Klappe",text:"das Teil 31 × 13 cm: um den Boden, an der Rückseite hoch, am Ende runde Ecken"},{title:"Fächer ×3",text:"Nähte 11 und 22 cm vom Bruch durch beide Hälften: Handy, Geld, Karten"},{title:"Schlaufen ×2",text:"Quadrate 5 × 5 cm, gefaltet wie die Henkel der Tote Bag, dann zur Schlaufe"},{title:"Druckknopf",text:"aus Kunststoff · mittig auf der Klappe, auf der Steppnaht"},{title:"Nähte",text:"alle 0,5 cm · 6 cm Wendeöffnung gegenüber der Klappe, geschlossen von der Steppnaht 0,5 cm ringsum"}]};export{t as default};
